import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, mix, smoothstep, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, SphereGeometry, CylinderGeometry, Color,
    DirectionalLight, PointLight, HemisphereLight, Box3, Vector3,
    DataTexture, RGBAFormat, EquirectangularReflectionMapping, LinearFilter
  } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#14141a', ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 0.65, hex: '#101017' }, { at: 1, hex: '#16161d' }]
  };
  const stops = colors.gradientStops ?? [{ at: 0, hex: colors.background }, { at: 1, hex: colors.ink }];

  const root = new Group();
  const timelines = [];
  const primHandles = [];
  const disposables = [];

  // ---- Studio environment (equirectangular softbox) so machined steel reflects ----
  function makeEnv() {
    const w = 32, h = 16;
    const data = new Uint8Array(w * h * 4);
    for (let j = 0; j < h; j++) {
      const v = j / (h - 1);
      let b = 0.05 + v * 0.22;
      const band = Math.exp(-Math.pow((v - 0.8) / 0.09, 2)) * 0.95; // top softbox
      b = Math.min(b + band, 1.0);
      for (let i = 0; i < w; i++) {
        const idx = (j * w + i) * 4;
        data[idx] = b * 224;
        data[idx + 1] = b * 230;
        data[idx + 2] = b * 242;
        data[idx + 3] = 255;
      }
    }
    const tex = new DataTexture(data, w, h, RGBAFormat);
    tex.mapping = EquirectangularReflectionMapping;
    tex.minFilter = LinearFilter;
    tex.magFilter = LinearFilter;
    tex.needsUpdate = true;
    return tex;
  }
  const envTex = makeEnv();
  disposables.push(envTex);

  // ---- Backdrop: vertical gradient + centered spotlight glow (breaks flat void) ----
  const cLow = new Color(stops[0].hex);
  const cMid = new Color(stops[Math.min(1, stops.length - 1)].hex);
  const cHigh = new Color(stops[stops.length - 1].hex);
  const cCenter = new Color('#20202c');

  const backdropMat = new MeshBasicNodeMaterial();
  {
    const y = uv().y;
    const low = vec3(cLow.r, cLow.g, cLow.b);
    const mid = vec3(cMid.r, cMid.g, cMid.b);
    const high = vec3(cHigh.r, cHigh.g, cHigh.b);
    const center = vec3(cCenter.r, cCenter.g, cCenter.b);
    const vg = mix(low, mid, smoothstep(0.0, 0.6, y));
    const vg2 = mix(vg, high, smoothstep(0.6, 1.0, y));
    const d = length(uv().sub(vec2(0.5, 0.56)));
    const glow = smoothstep(0.66, 0.0, d).mul(0.55);
    const final = mix(vg2, center, glow);
    backdropMat.colorNode = vec4(final, 1.0);
  }
  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);
  disposables.push(backdrop.geometry, backdropMat);

  // ---- Lights: product-shot rig tuned for metallic response, low red pollution ----
  const key = new DirectionalLight(0xffffff, 1.15);
  key.position.set(2.6, 3.0, 4.0);
  root.add(key);

  const topRim = new DirectionalLight(0xeef2f8, 0.7);
  topRim.position.set(-0.4, 4.2, 1.4);
  root.add(topRim);

  // Accent back-rim (signal red) strictly behind so it grazes edges, not the face
  const rim = new DirectionalLight(new Color(colors.accent).getHex(), 0.6);
  rim.position.set(-2.2, 1.2, -3.2);
  root.add(rim);

  const fill = new DirectionalLight(0xdfe6f0, 0.45);
  fill.position.set(-2.6, -0.8, 3.2);
  root.add(fill);

  // Hemisphere ambient gives metal a gradient to sample (cool sky / dark ground)
  const hemi = new HemisphereLight(0xdfe6f0, 0x0b0b10, 0.6);
  root.add(hemi);

  // Local jewel glow, tight radius so it does not wash the steel pink
  const jewelGlow = new PointLight(new Color(colors.accent).getHex(), 0.5, 1.2);
  jewelGlow.position.set(0, 0, 0.4);
  root.add(jewelGlow);

  // ---- Gear group ----
  const gearWorld = new Group();
  root.add(gearWorld);

  const primaryGear = new Group();
  const secondaryGear = new Group();
  secondaryGear.position.set(1.15, 0.35, -0.1);
  gearWorld.add(primaryGear);
  gearWorld.add(secondaryGear);

  function makeSteelMaterial() {
    const m = new MeshPhysicalNodeMaterial();
    m.color = new Color('#828a94');   // cool machined steel, mid albedo
    m.roughness = 0.5;
    m.metalness = 0.55;
    m.clearcoat = 0.2;
    m.clearcoatRoughness = 0.3;
    m.anisotropy = 0.7;
    m.anisotropyRotation = Math.PI / 2;
    m.envMap = envTex;
    m.envMapIntensity = 1.0;
    return m;
  }

  function orientAndNormalize(obj, targetDiameter) {
    obj.updateMatrixWorld(true);
    let box = new Box3().setFromObject(obj);
    const size = new Vector3();
    box.getSize(size);
    const min = Math.min(size.x, size.y, size.z);
    // Rotate so the flat (thin) axis faces the camera (+z), gear in xy plane
    if (min === size.y) obj.rotation.x = Math.PI / 2;
    else if (min === size.x) obj.rotation.y = Math.PI / 2;
    obj.updateMatrixWorld(true);

    box = new Box3().setFromObject(obj);
    box.getSize(size);
    const maxXY = Math.max(size.x, size.y) || 1;
    const s = targetDiameter / maxXY;
    obj.scale.setScalar(s);
    obj.updateMatrixWorld(true);

    box = new Box3().setFromObject(obj);
    const center = new Vector3();
    box.getCenter(center);
    obj.position.sub(center);
  }

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const srcScene = gltf.scene;

    const primaryMesh = srcScene.clone(true);
    const secondaryMesh = srcScene.clone(true);

    const steel = makeSteelMaterial();
    disposables.push(steel);
    primaryMesh.traverse((n) => { if (n.isMesh) n.material = steel; });

    const steel2 = makeSteelMaterial();
    disposables.push(steel2);
    secondaryMesh.traverse((n) => { if (n.isMesh) n.material = steel2; });

    orientAndNormalize(primaryMesh, 1.6);
    orientAndNormalize(secondaryMesh, 0.9);

    primaryGear.add(primaryMesh);
    secondaryGear.add(secondaryMesh);
  }).catch(() => { /* hubs / arbors / jewel remain visible */ });

  // ---- Arbor shafts (ink cylinders through hubs) ----
  const arborMat = new MeshPhysicalNodeMaterial();
  arborMat.color = new Color(colors.ink || '#16161d');
  arborMat.roughness = 0.4;
  arborMat.metalness = 0.5;
  arborMat.envMap = envTex;
  arborMat.envMapIntensity = 0.8;
  disposables.push(arborMat);

  const arborGeo = new CylinderGeometry(0.05, 0.05, 0.8, 24);
  disposables.push(arborGeo);
  const arbor1 = new Mesh(arborGeo, arborMat);
  arbor1.rotation.x = Math.PI / 2;
  primaryGear.add(arbor1);
  const arbor2 = new Mesh(arborGeo, arborMat);
  arbor2.rotation.x = Math.PI / 2;
  secondaryGear.add(arbor2);

  // ---- Jewel pivot (the single brightest, accent element) ----
  const jewelMat = new MeshPhysicalNodeMaterial();
  jewelMat.color = new Color(colors.accent);
  jewelMat.transmission = 0.6;
  jewelMat.ior = 1.76;
  jewelMat.thickness = 0.2;
  jewelMat.roughness = 0.12;
  jewelMat.metalness = 0.0;
  jewelMat.emissive = new Color(colors.accent);
  jewelMat.emissiveIntensity = 1.8;
  jewelMat.envMap = envTex;
  jewelMat.envMapIntensity = 0.6;
  disposables.push(jewelMat);
  const jewelGeo = new SphereGeometry(0.12, 32, 32);
  disposables.push(jewelGeo);
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.1);
  primaryGear.add(jewel);

  // ---- Contact shadow ellipse ----
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  {
    const d = length(uv().sub(vec2(0.5, 0.5)));
    const alpha = smoothstep(0.5, 0.0, d).mul(0.5);
    shadowMat.colorNode = vec4(vec3(0.0, 0.0, 0.0), alpha);
  }
  const shadow = new Mesh(new PlaneGeometry(2.6, 1.2), shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.2, 0);
  root.add(shadow);
  disposables.push(shadow.geometry, shadowMat);

  // ---- Text ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjs = [];
  const fallback = [
    { text: 'The going train', role: 'headline' },
    { text: '34 COMPONENTS / HAND-FINISHED', role: 'caption' }
  ];
  const srcItems = items.length ? items : fallback;

  for (const item of srcItems) {
    const role = item.role || 'caption';
    const content = String(item.text ?? '');
    let obj;
    if (role === 'headline') {
      obj = ctx.fontAtlas.createText(content, {
        fontSize: 68, color: colors.paper, align: 'center', letterSpacingPx: -0.5
      });
      obj.position.set(0, -1.7, 0.2);
    } else {
      obj = ctx.fontAtlas.createText(content, {
        fontSize: 18, color: colors.paper, align: 'center', letterSpacingPx: 1.6
      });
      obj.position.set(0, -2.1, 0.2);
    }
    root.add(obj);
    textObjs.push(obj);
  }

  // ---- Meshing rotation (phase-locked 16:9) ----
  const gearState = { t: 0 };
  const gearTl = gsap.timeline({ repeat: -1 });
  gearTl.to(gearState, {
    t: 1,
    duration: 100,
    ease: 'none',
    onUpdate: () => {
      primaryGear.rotation.z = gearState.t * 100 * 0.08;
      secondaryGear.rotation.z = gearState.t * 100 * -0.142;
    }
  });
  timelines.push(gearTl);

  // subtle jewel breathing (cap under 2.3)
  const jewelTl = gsap.timeline({ repeat: -1, yoyo: true });
  jewelTl.to(jewelMat, { emissiveIntensity: 2.2, duration: 2.2, ease: 'sine.inOut' });
  timelines.push(jewelTl);

  // ---- Entrance (weighted settle) ----
  gearWorld.scale.setScalar(0.9);
  const entrance = gsap.timeline();
  entrance.fromTo(gearWorld.scale, { x: 0.9, y: 0.9, z: 0.9 }, {
    x: 1.04, y: 1.04, z: 1.04, duration: 0.6, ease: 'power3.out'
  }).to(gearWorld.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
  for (const o of textObjs) {
    entrance.fromTo(o.position, { y: o.position.y + 0.3 }, { y: o.position.y, duration: 0.7, ease: 'power3.out' }, '<0.1');
  }
  timelines.push(entrance);

  // ---- Cinematic primitives ----
  const prims = config.cinematicPrimitives ?? [{ name: 'orbit', params: { speed: 0.08, radius: 0.2 }, trigger: 'time' }];
  for (const p of prims) {
    const fn = ctx.primitives[p.name];
    if (fn) {
      const h = fn(gearWorld, p.params || {});
      if (h) primHandles.push(h);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const tl of timelines) { try { tl.kill(); } catch (e) {} }
    for (const h of primHandles) { try { h.cleanup && h.cleanup(); } catch (e) {} }
    for (const d of disposables) { try { d.dispose && d.dispose(); } catch (e) {} }
    root.traverse((n) => {
      if (n.isMesh) {
        try { n.geometry && n.geometry.dispose(); } catch (e) {}
        try { n.material && n.material.dispose && n.material.dispose(); } catch (e) {}
      }
    });
  };

  return root;
}
